// TickChildren ticks child state machines (W3C SCXML 6.4).
// Port of Rust do_tick_children().
func (p *ABadInvokeArgumentIsReportedOncePolicy) TickChildren(engine *sce.Engine[ABadInvokeArgumentIsReportedOnceState, ABadInvokeArgumentIsReportedOnceEvent]) {
	if !p.pendingDoneInvokeInv1 && p.childInv1 != nil {
		child := p.childInv1
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv1", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv1", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeInv1 {
			p.pendingDoneInvokeInv1 = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("inv1", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeInv2 && p.childInv2 != nil {
		child := p.childInv2
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv2", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv2", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeInv2 {
			p.pendingDoneInvokeInv2 = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("inv2", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeInv3 && p.childInv3 != nil {
		child := p.childInv3
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv3", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv3", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeInv3 {
			p.pendingDoneInvokeInv3 = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("inv3", child.DonedataAtFinal(), engine)
		}
	}
}


// DeliverToChildSession delivers an event addressed to a child's published
// location (W3C SCXML C.1).
//
// The parent mints `parentSession.invokeId` for each child and that id is what
// the child's `_ioprocessors` entry names, so a <send> whose target decodes to
// one of them is addressed to that child rather than to this machine. A false
// return means the address names no live child of ours and the event takes the
// normal external path — the routing half of C.1 is what makes the published
// location a usable target rather than a string that merely compares equal.
func (p *ABadInvokeArgumentIsReportedOncePolicy) DeliverToChildSession(childSessionID, eventName, eventData string) bool {
	if childSessionID == "" {
		return false
	}
	if cs, ok := p.activeInvokes["inv1"]; ok && cs.SessionID == childSessionID {
		if p.childInv1 != nil {
			p.childInv1.RaiseExternalByName(eventName, eventData)
			return true
		}
	}
	if cs, ok := p.activeInvokes["inv2"]; ok && cs.SessionID == childSessionID {
		if p.childInv2 != nil {
			p.childInv2.RaiseExternalByName(eventName, eventData)
			return true
		}
	}
	if cs, ok := p.activeInvokes["inv3"]; ok && cs.SessionID == childSessionID {
		if p.childInv3 != nil {
			p.childInv3.RaiseExternalByName(eventName, eventData)
			return true
		}
	}
	return false
}


