// ======================================================================
// StatePolicy interface implementation
// ======================================================================

// InitialState returns the initial state (W3C SCXML 3.3).
func (p *ABadInvokeArgumentIsReportedOncePolicy) InitialState() ABadInvokeArgumentIsReportedOnceState {
	return ABadInvokeArgumentIsReportedOnceStateS0
}

// IsFinalState returns true if state is a <final> state (W3C SCXML 3.7).
func (p *ABadInvokeArgumentIsReportedOncePolicy) IsFinalState(state ABadInvokeArgumentIsReportedOnceState) bool {
	switch state {
	case ABadInvokeArgumentIsReportedOnceStateDone:
		return true
	}
	return false
}

// GetParent returns the parent of state, or (zero, false) if root (W3C SCXML 3.3).
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetParent(state ABadInvokeArgumentIsReportedOnceState) (ABadInvokeArgumentIsReportedOnceState, bool) {
	switch state {
	case ABadInvokeArgumentIsReportedOnceStateS0:
		return ABadInvokeArgumentIsReportedOnceStateRun, true
	case ABadInvokeArgumentIsReportedOnceStateS1:
		return ABadInvokeArgumentIsReportedOnceStateRun, true
	}
	return 0, false
}

// IsCompoundState returns true if state is a <state> with child states — exactly
// the states that have an initial transition. A <parallel> is not compound
// (W3C SCXML 3.3).
func (p *ABadInvokeArgumentIsReportedOncePolicy) IsCompoundState(state ABadInvokeArgumentIsReportedOnceState) bool {
	return len(initialTargetsOfABadInvokeArgumentIsReportedOnce[state]) > 0
}

func (p *ABadInvokeArgumentIsReportedOncePolicy) IsParallelState(_ ABadInvokeArgumentIsReportedOnceState) bool { return false }

// GetChildStates returns state's <state>, <parallel> and <final> children, in
// document order — for a <parallel>, its regions (§scxml-D-getChildStates).
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetChildStates(state ABadInvokeArgumentIsReportedOnceState) []ABadInvokeArgumentIsReportedOnceState {
	return childStatesOfABadInvokeArgumentIsReportedOnce[state]
}

// GetInitialTargets returns a compound state's initial transition target, as
// written; the engine's entry procedures dereference a <history> among them
// (W3C SCXML 3.3).
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetInitialTargets(state ABadInvokeArgumentIsReportedOnceState) []ABadInvokeArgumentIsReportedOnceTarget {
	return initialTargetsOfABadInvokeArgumentIsReportedOnce[state]
}

// GetDocumentInitialTargets returns the target of the document's own initial
// transition, as written (W3C SCXML 3.2).
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetDocumentInitialTargets() []ABadInvokeArgumentIsReportedOnceTarget {
	return documentInitialTargetsOfABadInvokeArgumentIsReportedOnce
}

// W3C SCXML 3.10: this document declares no <history>, so no target list names
// one and the engine never asks the two below; answering would mean inventing
// one.
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetHistoryParent(history sce.HistoryID) ABadInvokeArgumentIsReportedOnceState {
	panic(fmt.Sprintf("ABadInvokeArgumentIsReportedOncePolicy declares no <history>; asked for %d", history))
}
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetHistoryDefaultTargets(history sce.HistoryID) []ABadInvokeArgumentIsReportedOnceTarget {
	panic(fmt.Sprintf("ABadInvokeArgumentIsReportedOncePolicy declares no <history>; asked for %d", history))
}
func (p *ABadInvokeArgumentIsReportedOncePolicy) HistoryValue(_ sce.HistoryID) ([]ABadInvokeArgumentIsReportedOnceState, bool) {
	return nil, false
}

// GetDocumentOrder returns the document order index (W3C SCXML Appendix D).
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetDocumentOrder(state ABadInvokeArgumentIsReportedOnceState) int {
	switch state {
	case ABadInvokeArgumentIsReportedOnceStateDone:
		return 3
	case ABadInvokeArgumentIsReportedOnceStateRun:
		return 0
	case ABadInvokeArgumentIsReportedOnceStateS0:
		return 1
	case ABadInvokeArgumentIsReportedOnceStateS1:
		return 2
	}
	return -1
}

// GetEventName returns the string name of an event (W3C SCXML 3.12).
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetEventName(event ABadInvokeArgumentIsReportedOnceEvent) string {
	return event.String()
}

// GetEventFromName looks up an event by name (W3C SCXML 3.12).
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetEventFromName(name string) (ABadInvokeArgumentIsReportedOnceEvent, bool) {
	switch name {
	case "childUp":
		return ABadInvokeArgumentIsReportedOnceEventChildUp, true
	case "done.invoke":
		return ABadInvokeArgumentIsReportedOnceEventDoneInvoke, true
	case "error.execution":
		return ABadInvokeArgumentIsReportedOnceEventErrorExecution, true
	case "finish":
		return ABadInvokeArgumentIsReportedOnceEventFinish, true
	case "go":
		return ABadInvokeArgumentIsReportedOnceEventGo, true
	}
	return ABadInvokeArgumentIsReportedOnceEventNull, false
}

// GetStateName returns the string name of a state (W3C SCXML 3.3).
func (p *ABadInvokeArgumentIsReportedOncePolicy) GetStateName(state ABadInvokeArgumentIsReportedOnceState) string {
	return state.String()
}

